CREATE TABLE IF NOT EXISTS admin_settings (key TEXT PRIMARY KEY,value TEXT,updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS site_visits (id SERIAL PRIMARY KEY,path TEXT NOT NULL,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS services (id SERIAL PRIMARY KEY,slug TEXT UNIQUE NOT NULL,name TEXT NOT NULL,name_en TEXT,tagline TEXT,tagline_en TEXT,body TEXT,body_en TEXT,signs TEXT,signs_en TEXT,icon TEXT,duration_min INTEGER DEFAULT 60 CHECK(duration_min>=0 AND duration_min<=600),price_from_cents INTEGER CHECK(price_from_cents IS NULL OR price_from_cents>=0),price_verified INTEGER DEFAULT 0,bookable INTEGER DEFAULT 1,featured INTEGER DEFAULT 0,option_kind TEXT,published INTEGER DEFAULT 1,sort_order INTEGER DEFAULT 0,image_url TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS hours (id SERIAL PRIMARY KEY,weekday INTEGER NOT NULL UNIQUE CHECK(weekday BETWEEN 1 AND 7),opens TEXT,closes TEXT,closed INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS closures (id SERIAL PRIMARY KEY,date DATE NOT NULL UNIQUE,reason TEXT,reason_en TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS customer_profiles (id SERIAL PRIMARY KEY,user_id TEXT UNIQUE NOT NULL,first_name TEXT,last_name TEXT,phone TEXT,language TEXT DEFAULT 'fr',notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS vehicles (id SERIAL PRIMARY KEY,user_id TEXT NOT NULL,year INTEGER CHECK(year IS NULL OR (year>=1950 AND year<=2100)),make TEXT,model TEXT,trim TEXT,vin TEXT,plate TEXT,odometer_km INTEGER CHECK(odometer_km IS NULL OR odometer_km>=0),last_oil_km INTEGER,last_oil_date DATE,notes TEXT,archived INTEGER DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS vehicles_user_idx ON vehicles(user_id);
CREATE TABLE IF NOT EXISTS appointments (id SERIAL PRIMARY KEY,reference TEXT UNIQUE,user_id TEXT NOT NULL,request_key TEXT,vehicle_id INTEGER REFERENCES vehicles(id) ON DELETE SET NULL,vehicle_label TEXT,services TEXT,service_names TEXT,concern TEXT,start_at TIMESTAMPTZ NOT NULL,end_at TIMESTAMPTZ NOT NULL,duration_min INTEGER NOT NULL,bay INTEGER,stay TEXT DEFAULT 'drop' CHECK(stay IN ('drop','wait')),courtesy_car INTEGER DEFAULT 0,towing INTEGER DEFAULT 0,towing_address TEXT,contact_name TEXT NOT NULL,contact_phone TEXT,contact_email TEXT,language TEXT DEFAULT 'fr',status TEXT NOT NULL DEFAULT 'requested' CHECK(status IN ('holding','requested','confirmed','in_progress','ready','completed','cancelled','no_show')),preview INTEGER DEFAULT 0,garage_note TEXT,internal_note TEXT,consent INTEGER DEFAULT 0,privacy_snapshot TEXT,confirmed_at TIMESTAMPTZ,cancelled_at TIMESTAMPTZ,cancelled_by TEXT,reminder_sent_at TIMESTAMPTZ,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),UNIQUE(user_id,request_key));
CREATE INDEX IF NOT EXISTS appointments_start_idx ON appointments(start_at);
CREATE INDEX IF NOT EXISTS appointments_user_idx ON appointments(user_id);
CREATE TABLE IF NOT EXISTS bay_slots (bay INTEGER NOT NULL,slot_at TIMESTAMPTZ NOT NULL,appointment_id INTEGER NOT NULL REFERENCES appointments(id) ON DELETE CASCADE,PRIMARY KEY(bay,slot_at));
CREATE INDEX IF NOT EXISTS bay_slots_appt_idx ON bay_slots(appointment_id);
CREATE TABLE IF NOT EXISTS appointment_events (id SERIAL PRIMARY KEY,appointment_id INTEGER NOT NULL REFERENCES appointments(id) ON DELETE CASCADE,status TEXT,note TEXT,actor TEXT,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS appointment_events_appt_idx ON appointment_events(appointment_id);
CREATE TABLE IF NOT EXISTS messages (id SERIAL PRIMARY KEY,first_name TEXT NOT NULL,last_name TEXT,email TEXT NOT NULL,phone TEXT,subject TEXT,body TEXT NOT NULL,consent INTEGER DEFAULT 0,privacy_snapshot TEXT,status TEXT DEFAULT 'new' CHECK(status IN ('new','read','answered','archived')),created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE IF NOT EXISTS clients (id SERIAL PRIMARY KEY,user_id TEXT UNIQUE,name TEXT NOT NULL,phone TEXT,email TEXT,address TEXT,notes TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS clients_name_idx ON clients(LOWER(name));
CREATE TABLE IF NOT EXISTS documents (id SERIAL PRIMARY KEY,kind TEXT NOT NULL CHECK(kind IN ('estimate','invoice')),number TEXT UNIQUE,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','accepted','declined','invoiced','unpaid','paid','void')),client_id INTEGER REFERENCES clients(id) ON DELETE SET NULL,vehicle_id INTEGER REFERENCES vehicles(id) ON DELETE SET NULL,appointment_id INTEGER REFERENCES appointments(id) ON DELETE SET NULL,source_id INTEGER REFERENCES documents(id) ON DELETE SET NULL,client_name TEXT,client_phone TEXT,client_email TEXT,client_address TEXT,vehicle_label TEXT,vehicle_plate TEXT,vehicle_vin TEXT,odometer_km INTEGER CHECK(odometer_km IS NULL OR odometer_km>=0),issued_on DATE,valid_until DATE,delivered_on DATE,labour_rate_cents INTEGER,charge_taxes INTEGER DEFAULT 1,subtotal_cents INTEGER DEFAULT 0,tps_cents INTEGER DEFAULT 0,tvq_cents INTEGER DEFAULT 0,total_cents INTEGER DEFAULT 0,paid_cents INTEGER DEFAULT 0,payment_method TEXT,paid_on DATE,return_parts INTEGER DEFAULT 0,customer_note TEXT,internal_note TEXT,warranty_text TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX IF NOT EXISTS documents_kind_idx ON documents(kind, status, created_at DESC);
CREATE TABLE IF NOT EXISTS document_lines (id SERIAL PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES documents(id) ON DELETE CASCADE,position INTEGER DEFAULT 0,kind TEXT NOT NULL CHECK(kind IN ('part','labour','fee','note')),description TEXT NOT NULL,part_condition TEXT CHECK(part_condition IS NULL OR part_condition IN ('new','used','reman','recond')),part_number TEXT,quantity NUMERIC(10,2) DEFAULT 1,unit_cents INTEGER DEFAULT 0,total_cents INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS document_counters (kind TEXT PRIMARY KEY,next_number INTEGER NOT NULL DEFAULT 1);
